{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Ketoprofen, a benzoyl-substituted arylpropionic acid NSAID with the same benzoyl ketone and carboxylic acid pharmacophore as the query, has an absolute oral bioavailability of 92% in humans, directly supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiaprofenic acid, another benzoyl-substituted arylpropionic acid NSAID, is almost completely absorbed with an oral bioavailability of about 90-100%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Solifenacin, a lipophilic drug with high absolute oral bioavailability of about 90% in healthy adults, provides weaker but supportive evidence that high F is plausible for the query's lipophilic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Endralazine has a mean oral bioavailability of 75% in normal subjects, supporting high F, although its structural transferability to the query is limited.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ketorolac, an acidic NSAID bearing a benzoyl ketone and carboxylic acid. The closest structural analogues, ketoprofen and tiaprofenic acid, show high absolute oral bioavailability (92% and 90-100%), strongly supporting F>=20%. Additional high-F drugs provide weaker support; low-F basic amine drugs are structurally dissimilar and not transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability study for the query molecule was retrieved; the prediction relies on close NSAID analogues with low Morgan similarity scores.",
    "No query-specific data on first-pass metabolism or solubility were available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

